import subprocess, pathlib, re, os
kok = pathlib.Path(".")
env = kok / "mobil" / ".env"
files = subprocess.run(["git","ls-files","--others","--exclude-standard","docs/oturumlar/"],capture_output=True,text=True).stdout.split()
degerler = []
for satir in env.read_text(encoding="utf-8", errors="replace").splitlines():
    if "=" in satir and not satir.strip().startswith("#"):
        ad, _, deg = satir.partition("=")
        deg = deg.strip().strip('"').strip("'")
        if len(deg) >= 8:
            degerler.append((ad.strip(), deg))
print(f"kontrol edilen .env anahtari: {len(degerler)}")
icerik = {}
for f in files:
    try:
        icerik[f] = pathlib.Path(f).read_text(encoding="utf-8", errors="replace")
    except Exception as e:
        print("okunamadi:", f, type(e).__name__)
for ad, deg in degerler:
    vurulan = [f for f, s in icerik.items() if deg in s]
    print(f"{ad}: {len(vurulan)} dosyada geciyor" + (" -> " + ", ".join(vurulan[:5]) if vurulan else ""))
PY

