select
  (select count(*) from public.mekanlar) as mekan_sayisi,
  (select string_agg(distinct tur, ', ') from public.mekanlar) as turler;
select indexname, indexdef from pg_indexes where tablename = 'mekanlar';
select column_name, data_type from information_schema.columns
 where table_name = 'mekanlar' order by ordinal_position;

select p.proname, pg_get_function_arguments(p.oid) as args
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.proname like '%mekan%';

-- Uygulamanin gercek arama yolu: kimlik taklidiyle authenticated olarak cagir
select m.ad, m.tur, round(m.mesafe_metre) as mesafe
from (select set_config('request.jwt.claims',
  (select json_build_object('sub', id, 'role', 'authenticated')::text
     from auth.users limit 1), true)) s,
lateral (
  select * from public.yakin_mekanlar_yogunluk(40.9871, 29.0258, 1000, null) limit 10
) m;

select m.*
from (select set_config('request.jwt.claims',
  (select json_build_object('sub', id, 'role', 'authenticated')::text
     from auth.users limit 1), true)) s,
lateral (
  select * from public.yakin_mekanlar_yogunluk(40.9871, 29.0258, 1000, null) limit 8
) m;

