-- Kolonlar bos donmus olabilir, tekrar dene + RLS ve durum degerlerini gor
select column_name, data_type from information_schema.columns
where table_schema='public' and table_name='sikayetler' order by ordinal_position;
select conname, pg_get_constraintdef(oid) from pg_constraint
where conrelid='public.sikayetler'::regclass and contype='c';
select policyname, cmd, roles::text from pg_policies where tablename='sikayetler';
-- engelleme/sikayet ile ilgili moderasyon araci var mi
select proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where n.nspname='public' and (proname like '%sikayet%' or proname like '%moder%' or proname like '%askiya%' or proname like '%yasakla%');

select json_build_object(
  'kolonlar', (select json_agg(json_build_object('ad', column_name, 'tip', data_type))
     from information_schema.columns where table_schema='public' and table_name='sikayetler'),
  'kisitlar', (select json_agg(pg_get_constraintdef(oid))
     from pg_constraint where conrelid='public.sikayetler'::regclass and contype='c'),
  'politikalar', (select json_agg(json_build_object('ad', policyname, 'cmd', cmd, 'roller', roles::text))
     from pg_policies where tablename='sikayetler'),
  'rls_acik', (select relrowsecurity from pg_class where oid='public.sikayetler'::regclass)
) as sema;

